using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using System.IO;using System.Linq;
public class CharacterQuickStart:EditorWindow {
[MenuItem("Classroom/Character Tutorial")] public static void Open(){GetWindow<CharacterQuickStart>("Character Tutorial");}
void OnGUI(){GUILayout.Label("ANIMATED HUMAN / UNITY",EditorStyles.boldLabel);EditorGUILayout.HelpBox("Download an animated FBX from your own Mixamo account: FBX for Unity, With Skin, 30 FPS. Rename it Character.fbx and put it in Assets.",MessageType.Info);if(GUILayout.Button("1  Select Character.fbx"))Selection.activeObject=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Character.fbx");if(GUILayout.Button("2  Configure Humanoid + extract textures"))Configure();if(GUILayout.Button("3  Build animation demo scene"))Build();if(GUILayout.Button("4  Open Game view"))EditorApplication.ExecuteMenuItem("Window/General/Game");GUILayout.Label("Press Unity's Play triangle. This is a desktop lesson, not a device AR test.");}
static void Configure(){var p="Assets/Character.fbx";var im=AssetImporter.GetAtPath(p) as ModelImporter;if(im==null){EditorUtility.DisplayDialog("Add an FBX","Copy your Mixamo FBX into Assets and name it Character.fbx.","OK");return;}im.animationType=ModelImporterAnimationType.Human;im.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;im.importAnimation=true;im.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;im.SaveAndReimport();Directory.CreateDirectory("Assets/Textures");im.ExtractTextures("Assets/Textures");AssetDatabase.Refresh();var clips=im.clipAnimations;if(clips.Length==0)clips=im.defaultClipAnimations;foreach(var clip in clips)clip.loopTime=true;im.clipAnimations=clips;
Directory.CreateDirectory("Assets/Materials");var names=AssetDatabase.LoadAllAssetsAtPath(p).OfType<Material>().Select(m=>m.name).ToArray();foreach(var name in names){var m=new Material(Shader.Find("Standard"));var token=name.Replace("mat","");if(token=="Eyelash")token="Body";var guids=AssetDatabase.FindAssets("t:Texture2D "+token+"_Diffuse",new[]{"Assets/Textures"});if(guids.Length>0)m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(AssetDatabase.GUIDToAssetPath(guids[0]));m.SetFloat("_Glossiness",.15f);if(name.Contains("Hair")||name.Contains("Eyelash")){m.SetFloat("_Mode",1);m.EnableKeyword("_ALPHATEST_ON");m.SetFloat("_Cutoff",.3f);m.renderQueue=2450;}var mp="Assets/Materials/"+name+".mat";var existing=AssetDatabase.LoadAssetAtPath<Material>(mp);if(existing)m=existing;else AssetDatabase.CreateAsset(m,mp);im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),name),m);}im.SaveAndReimport();Selection.activeObject=AssetDatabase.LoadAssetAtPath<GameObject>(p);}
static void Build(){var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Character.fbx");var clip=AssetDatabase.LoadAllAssetsAtPath("Assets/Character.fbx").OfType<AnimationClip>().FirstOrDefault(c=>!c.name.StartsWith("__"));if(!model||!clip){EditorUtility.DisplayDialog("Animated FBX required","Download With Skin from Mixamo, not the static CC0 source model.","OK");return;}if(!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=(GameObject)PrefabUtility.InstantiatePrefab(model);var animator=go.GetComponent<Animator>();var path="Assets/CharacterDance.controller";var ctl=AssetDatabase.LoadAssetAtPath<AnimatorController>(path);if(!ctl){ctl=AnimatorController.CreateAnimatorControllerAtPath(path);ctl.AddMotion(clip);}animator.runtimeAnimatorController=ctl;animator.applyRootMotion=false;
var b=new Bounds(go.transform.position,Vector3.zero);foreach(var r in go.GetComponentsInChildren<Renderer>())b.Encapsulate(r.bounds);float h=b.size.y;var cam=new GameObject("Main Camera").AddComponent<Camera>();cam.tag="MainCamera";cam.transform.position=b.center+new Vector3(0,h*.1f,h*2);cam.transform.LookAt(b.center);cam.fieldOfView=35;cam.nearClipPlane=.01f;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.93f,.95f,.95f);var light=new GameObject("Key Light").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.5f;light.transform.rotation=Quaternion.Euler(35,-35,0);RenderSettings.ambientLight=new Color(.65f,.65f,.65f);EditorSceneManager.SaveScene(scene,"Assets/CharacterDemo.unity");Selection.activeGameObject=go;}
}
